FROM kb_document_chunk c
INNER JOIN kb_document d ON d.id = c.document_id AND d.is_delete = 0
WHERE c.is_delete = 0

    AND c.space_id IN

        #{sid}



    AND c.status = #{status}


    AND c.kb_type IN

        #{t}



    AND c.kb_type NOT IN

        #{t}

mapper.select:
SELECT c.id AS chunkId, c.document_id AS documentId, c.space_id AS spaceId, c.slug, d.title, d.summary, c.kb_type AS kbType, c.heading, c.content, c.chunk_index AS chunkIndex
AND MATCH(c.heading, c.content) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE)
ORDER BY MATCH(c.heading, c.content) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE) DESC, c.chunk_index ASC LIMIT #{limit}

SELECT c.id AS chunkId, c.document_id AS documentId, c.space_id AS spaceId, c.slug, d.title, d.summary, c.kb_type AS kbType, c.heading, c.content, c.chunk_index AS chunkIndex
AND ( c.heading LIKE CONCAT('%', #{keyword}, '%') OR c.content LIKE CONCAT('%', #{keyword}, '%') OR d.title LIKE CONCAT('%', #{keyword}, '%') OR d.summary LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.update_time DESC, c.chunk_index ASC LIMIT #{limit}

SELECT c.id AS chunkId, c.document_id AS documentId, c.space_id AS spaceId, c.slug, d.title, d.summary, c.kb_type AS kbType, c.heading, c.content, c.chunk_index AS chunkIndex FROM kb_document_chunk c INNER JOIN kb_document d ON d.id = c.document_id AND d.is_delete = 0 WHERE c.is_delete = 0
AND c.status = #{status}
AND c.id IN
#{cid}
ORDER BY c.chunk_index ASC

SELECT chunkId, documentId, spaceId, slug, title, summary, kbType, heading, content, chunkIndex FROM ( SELECT c.id AS chunkId, c.document_id AS documentId, c.space_id AS spaceId, c.slug, d.title, d.summary, c.kb_type AS kbType, c.heading, c.content, c.chunk_index AS chunkIndex, ROW_NUMBER() OVER ( PARTITION BY c.document_id ORDER BY
CASE WHEN c.heading LIKE CONCAT('%', #{keyword}, '%') OR c.content LIKE CONCAT('%', #{keyword}, '%') THEN 0 ELSE 1 END,
c.chunk_index ASC ) AS rn FROM kb_document_chunk c INNER JOIN kb_document d ON d.id = c.document_id AND d.is_delete = 0 WHERE c.is_delete = 0
AND c.status = #{status}
AND c.space_id IN
#{sid}
AND c.document_id IN
#{did}
) ranked WHERE ranked.rn <= #{perDoc} ORDER BY documentId ASC, chunkIndex ASC
